/* Province outlines for the map on the home page.
 *
 * The map used to be a 5.8 MB photograph of Google Maps with the pins floated
 * on top in percentages, and the region a factor covers drawn as a circle.
 * These are the real boundaries, so a province can be filled, raised and
 * hovered as itself.
 *
 * All 77 are here. For a while only the 13 of the industrial belt were, which
 * meant the map had to zoom into them and the country had no shape around it —
 * the highlighted block floated in an empty box. The other 64 are backdrop and
 * are simplified far harder (~2.2 km against ~240 m) to keep this file small;
 * `hi` marks the 13 that can be highlighted, hovered and carry pins, and they
 * keep the tight tolerance because the ports sit on the coastline: at 650 m the
 * simplifier cut inside Laem Chabang and the pin fell outside Chonburi.
 *
 * Source: Natural Earth 1:10m admin-1 (public domain).
 * Coordinates are [lng, lat], the order GeoJSON uses.
 */
export type Province = { key: string; th: string; hi: boolean; rings: [number, number][][] };

